public class ApiKeyOptions : AuthenticationSchemeOptions
{
    public const string Scheme = "ApiKey";
    public string HeaderName { get; set; } = "X-Api-Key";
}

public class ApiKeyHandler(
    IOptionsMonitor<ApiKeyOptions> options,
    ILoggerFactory logger,
    UrlEncoder encoder,
    IApiKeyValidator validator) : AuthenticationHandler<ApiKeyOptions>(options, logger, encoder)
{
    protected override async Task<AuthenticateResult> HandleAuthenticateAsync()
    {
        if (!Request.Headers.TryGetValue(Options.HeaderName, out var keyValues))
            return AuthenticateResult.NoResult();

        var key = keyValues.ToString();
        var client = await validator.ValidateAsync(key, Context.RequestAborted);
        if (client is null)
            return AuthenticateResult.Fail("Invalid API key");

        var claims = new[]
        {
            new Claim("client_id", client.ClientId),
            new Claim(ClaimTypes.Role, "ApiClient")
        };
        var identity = new ClaimsIdentity(claims, ApiKeyOptions.Scheme);
        return AuthenticateResult.Success(
            new AuthenticationTicket(new ClaimsPrincipal(identity), ApiKeyOptions.Scheme));
    }
}

