public class ApiKeyValidator(AppDbContext db) : IApiKeyValidator
{
    public async Task<ApiClient?> ValidateAsync(string rawKey, CancellationToken ct)
    {
        var prefix = rawKey[..8]; // lookup index — not secret
        var candidates = await db.ApiKeys
            .Where(k => k.Prefix == prefix && k.IsActive)
            .ToListAsync(ct);

        foreach (var row in candidates)
        {
            if (BCrypt.Net.BCrypt.Verify(rawKey, row.KeyHash))
                return row.Client;
        }
        return null;
    }
}

